	Webhooks []webhookJSON `json:"webhooks"`
	Count    int           `json:"count"`
}

type webhookJSON struct {
	ID      string   `json:"id"`
	Name    string   `json:"name"`
	URL     string   `json:"url"`
	Format  string   `json:"format"`
	Active  bool     `json:"active"`
	Groups  []string `json:"eventGroups"`
	Filters []string `json:"events"`
}

func toWebhookJSON(wh apitype.Webhook) webhookJSON {
	format := ""
	if wh.Format != nil {
		format = *wh.Format
	}
	groups := wh.Groups
	if groups == nil {
		groups = []string{}
	}
	filters := wh.Filters
	if filters == nil {
		filters = []string{}
	}
	return webhookJSON{
		ID:      wh.Name,
		Name:    wh.DisplayName,
		URL:     wh.PayloadURL,
		Format:  format,
		Active:  wh.Active,
		Groups:  groups,
		Filters: filters,
	}
}

func renderWebhookListJSON(w io.Writer, webhooks []apitype.Webhook) error {
	items := make([]webhookJSON, 0, len(webhooks))
	for _, wh := range webhooks {
		items = append(items, toWebhookJSON(wh))
	}
	enc := json.NewEncoder(w)
	enc.SetEscapeHTML(false)
	enc.SetIndent("", "  ")
	return enc.Encode(webhookListEnvelope{
		Webhooks: items,
		Count:    len(items),
	})
}

