// Schedule kinds accepted by `pulumi stack schedule new --kind`.
const (
	scheduleKindRaw   = "raw"
	scheduleKindDrift = "drift"
	scheduleKindTTL   = "ttl"
)

// scheduleSummary is a flattened, human-readable summary of a scheduled action. It is also the
// JSON output shape used by the list and get commands.
type scheduleSummary struct {
	ID       string `json:"id"`
	Type     string `json:"type"`
	Settings string `json:"settings"`
	Schedule string `json:"schedule"`
	NextRun  string `json:"nextRun,omitempty"`
	LastRun  string `json:"lastRun,omitempty"`
	Created  string `json:"created,omitempty"`
}

// scheduleGetRenderFunc renders a single scheduled action. Used by the get, new, and edit commands.
type scheduleGetRenderFunc func(w io.Writer, schedule apitype.ScheduledAction) error

// scheduleListRenderFunc renders a list of scheduled actions. Used by the list command.
type scheduleListRenderFunc func(w io.Writer, schedules []apitype.ScheduledAction) error

// scheduleDeploymentInfo holds the operation-level details extracted from a scheduled action's
// deployment definition.
type scheduleDeploymentInfo struct {
	op                 apitype.PulumiOperation
	deleteAfterDestroy bool
	autoRemediate      bool
	request            *apitype.CreateDeploymentRequest
}

// scheduleDefinitionInfo parses the deployment definition embedded in a scheduled action.
func scheduleDefinitionInfo(s apitype.ScheduledAction) scheduleDeploymentInfo {
	var info scheduleDeploymentInfo
	if len(s.Definition) == 0 {
		return info
	}

	var def apitype.ScheduledDeploymentDefinition
	if err := json.Unmarshal(s.Definition, &def); err != nil {
		return info
	}
	if def.Request == nil {
		return info
	}
	info.request = def.Request
	info.op = def.Request.Op
	if def.Request.Operation != nil && def.Request.Operation.Options != nil {
		info.deleteAfterDestroy = def.Request.Operation.Options.DeleteAfterDestroy
		info.autoRemediate = def.Request.Operation.Options.RemediateIfDriftDetected
	}
	return info
}

// scheduleKindOf infers the schedule kind (raw, drift, or ttl) from a scheduled action.
func scheduleKindOf(s apitype.ScheduledAction) string {
	info := scheduleDefinitionInfo(s)
	switch {
	case info.op == apitype.Destroy && s.ScheduleOnce != "":
		return scheduleKindTTL
	case info.op == apitype.DetectDrift:
		return scheduleKindDrift
	default:
		return scheduleKindRaw
	}
}

// toScheduleSummary converts a scheduled action into its flattened summary form, inferring the
// type and settings from the deployment definition and timing fields.
func toScheduleSummary(s apitype.ScheduledAction) scheduleSummary {
	summary := scheduleSummary{
		ID:      s.ID,
		NextRun: s.NextExecution,
		Created: s.Created,
	}
	if s.LastExecuted != nil {
		summary.LastRun = *s.LastExecuted
	}

	switch {
	case s.ScheduleOnce != "":
		summary.Schedule = "Once"
	case s.ScheduleCron != "":
		summary.Schedule = s.ScheduleCron
	}

	info := scheduleDefinitionInfo(s)
	switch {
	case info.op == apitype.Destroy && s.ScheduleOnce != "":
		summary.Type = scheduleKindTTL
		if info.deleteAfterDestroy {
			summary.Settings = "destroy + delete stack"
		} else {
			summary.Settings = "destroy"
		}
	case info.op == apitype.DetectDrift:
		summary.Type = scheduleKindDrift
		summary.Settings = "detect"
	default:
		summary.Type = scheduleKindRaw
		summary.Settings = "pulumi " + string(info.op)
	}

	return summary
}

